package com.hospital.dao;
import com.hospital.util.DBConnection;import java.sql.*;import java.util.*;
public class MedicalRecordDAO {
 public long create(long appointment,String symptoms,String diagnosis,String notes,long user)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{long patient,doctor;try(PreparedStatement p=c.prepareStatement("SELECT a.patient_id,a.doctor_id,a.status FROM appointments a JOIN users u ON u.user_id=? AND u.doctor_id=a.doctor_id WHERE a.appointment_id=? AND u.role='DOCTOR' FOR UPDATE")){p.setLong(1,user);p.setLong(2,appointment);try(ResultSet r=p.executeQuery()){if(!r.next()||!"COMPLETED".equals(r.getString("status")))throw new SQLException("A completed appointment is required.");patient=r.getLong(1);doctor=r.getLong(2);}}long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO medical_records(appointment_id,patient_id,doctor_id,symptoms,diagnosis,notes,visit_at,created_by,updated_by) SELECT ?,?,?, ?,?,?,start_at,?,? FROM appointments WHERE appointment_id=?",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,appointment);p.setLong(2,patient);p.setLong(3,doctor);p.setString(4,symptoms);p.setString(5,diagnosis);p.setString(6,notes);p.setLong(7,user);p.setLong(8,user);p.setLong(9,appointment);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}c.commit();return id;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public List<String> history(long patient,Long doctor)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT record_id,visit_at,diagnosis FROM medical_records WHERE patient_id=? AND (? IS NULL OR doctor_id=?) ORDER BY visit_at DESC LIMIT 100")){p.setLong(1,patient);if(doctor==null){p.setNull(2,Types.BIGINT);p.setNull(3,Types.BIGINT);}else{p.setLong(2,doctor);p.setLong(3,doctor);}try(ResultSet r=p.executeQuery()){List<String> out=new ArrayList<>();while(r.next())out.add(r.getLong(1)+" | "+r.getTimestamp(2)+" | "+r.getString(3));return out;}}}
}
